// axi4_lite_regs_tb: self-checking testbench for axi4_lite_regs.
// Inputs are driven after the falling edge and sampled 1 time unit before
// the rising edge, so there is no race with the design.
`default_nettype none

`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error msg; end end
`define FAIL(msg) begin failed = failed + 1; $error msg; end

module axi4_lite_regs_tb;

    reg         aclk = 1'b0;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    always #5 aclk = ~aclk;

    // ------------------------------------------------------------------
    // Bookkeeping and reference model
    // ------------------------------------------------------------------
    integer        passed;
    integer        failed;
    integer        plus_ok;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];
    reg [31:0]     lfsr;

    integer        k;
    reg [3:0]      a;
    reg [31:0]     v;
    reg [31:0]     d;
    reg            r_wr;
    reg            r_rd;
    reg [3:0]      r_waddr;
    reg [3:0]      r_raddr;
    reg [3:0]      r_strb;
    integer        dly_aw;
    integer        dly_w;
    integer        dly_b;
    integer        dly_ar;
    integer        dly_r;

    // run_txn state
    integer        t_cyc;
    reg            t_aw_done;
    reg            t_w_done;
    reg            t_aw_hs;
    reg            t_w_hs;
    reg            t_wr_fin;
    reg            t_b_seen;
    integer        t_wr_cmp;
    integer        t_b_cyc;
    integer        t_wr_fin_cyc;
    reg [1:0]      t_b_exp;
    reg [1:0]      t_b_hold;
    reg            t_ar_done;
    reg            t_rd_fin;
    reg            t_r_seen;
    integer        t_ar_cyc;
    integer        t_r_cyc;
    integer        t_rd_fin_cyc;
    reg [31:0]     t_r_exp_data;
    reg [31:0]     t_r_hold_data;
    reg [1:0]      t_r_exp_resp;
    reg [1:0]      t_r_hold_resp;

    function tb_mapped;
        input [3:0] addr;
        begin
            tb_mapped = (addr[1:0] == 2'b00);
        end
    endfunction

    function [31:0] tb_merge;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  strb;
        begin
            tb_merge = { (strb[3] ? new_v[31:24] : old_v[31:24]),
                         (strb[2] ? new_v[23:16] : old_v[23:16]),
                         (strb[1] ? new_v[15:8]  : old_v[15:8]),
                         (strb[0] ? new_v[7:0]   : old_v[7:0]) };
        end
    endfunction

    task rnd_step;
        begin
            lfsr = lfsr ^ (lfsr << 13);
            lfsr = lfsr ^ (lfsr >> 17);
            lfsr = lfsr ^ (lfsr << 5);
        end
    endtask

    task model_clear;
        begin
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
        end
    endtask

    task idle_inputs;
        begin
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_arvalid = 1'b0;
            s_axil_bready  = 1'b0;
            s_axil_rready  = 1'b0;
        end
    endtask

    // ------------------------------------------------------------------
    // Reset: two cycles low, then check idle and ready.
    // ------------------------------------------------------------------
    task do_reset;
        begin
            @(negedge aclk);
            idle_inputs;
            aresetn = 1'b0;
            @(negedge aclk);
            #4;
            `CHECK(!s_axil_bvalid && !s_axil_rvalid, ("reset: BVALID or RVALID high during reset"))
            @(negedge aclk);
            aresetn = 1'b1;
            #4;
            `CHECK(!s_axil_bvalid && !s_axil_rvalid, ("reset: BVALID or RVALID high after reset"))
            `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("reset: READY low after reset"))
            model_clear;
        end
    endtask

    // ------------------------------------------------------------------
    // One write and/or one read, driven cycle by cycle with delays.
    // aw_dly/w_dly/ar_dly: cycles before VALID rises.
    // b_dly/r_dly: cycles READY stays low after the response appears.
    // ------------------------------------------------------------------
    task run_txn;
        input         do_wr;
        input  [3:0]  waddr;
        input  [31:0] wdat;
        input  [3:0]  wstr;
        input integer aw_dly;
        input integer w_dly;
        input integer b_dly;
        input         do_rd;
        input  [3:0]  raddr;
        input integer ar_dly;
        input integer r_dly;
        begin
            t_wr_fin      = !do_wr;
            t_rd_fin      = !do_rd;
            t_aw_done     = 1'b0;
            t_w_done      = 1'b0;
            t_aw_hs       = 1'b0;
            t_w_hs        = 1'b0;
            t_b_seen      = 1'b0;
            t_wr_cmp      = -1;
            t_b_cyc       = -1;
            t_wr_fin_cyc  = -10;
            t_b_exp       = tb_mapped(waddr) ? 2'b00 : 2'b10;
            t_b_hold      = 2'b00;
            t_ar_done     = 1'b0;
            t_r_seen      = 1'b0;
            t_ar_cyc      = -1;
            t_r_cyc       = -1;
            t_rd_fin_cyc  = -10;
            t_r_exp_data  = 32'h0000_0000;
            t_r_exp_resp  = 2'b00;
            t_r_hold_data = 32'h0000_0000;
            t_r_hold_resp = 2'b00;
            t_cyc         = 0;
            while ((!t_wr_fin || !t_rd_fin) && (t_cyc < 64)) begin
                @(negedge aclk);
                s_axil_awvalid = do_wr && !t_aw_done && (t_cyc >= aw_dly);
                s_axil_awaddr  = s_axil_awvalid ? waddr : ~waddr;
                s_axil_wvalid  = do_wr && !t_w_done && (t_cyc >= w_dly);
                s_axil_wdata   = s_axil_wvalid ? wdat : ~wdat;
                s_axil_wstrb   = s_axil_wvalid ? wstr : ~wstr;
                s_axil_bready  = do_wr && !t_wr_fin &&
                                 ((b_dly == 0) || (t_b_seen && ((t_cyc - t_b_cyc) >= b_dly)));
                s_axil_arvalid = do_rd && !t_ar_done && (t_cyc >= ar_dly);
                s_axil_araddr  = s_axil_arvalid ? raddr : ~raddr;
                s_axil_rready  = do_rd && !t_rd_fin &&
                                 ((r_dly == 0) || (t_r_seen && ((t_cyc - t_r_cyc) >= r_dly)));
                #4;

                // ---------------- read channel ----------------
                if (do_rd && !t_rd_fin) begin
                    if (s_axil_rvalid) begin
                        `CHECK(t_ar_done, ("R: RVALID high before AR was accepted (addr %h)", raddr))
                        if (!t_r_seen) begin
                            t_r_seen = 1'b1;
                            t_r_cyc  = t_cyc;
                            `CHECK(((t_cyc - t_ar_cyc) >= 1) && ((t_cyc - t_ar_cyc) <= 2),
                                   ("R: latency %0d cycles, bound is 1 to 2", t_cyc - t_ar_cyc))
                            `CHECK(s_axil_rdata == t_r_exp_data,
                                   ("R: addr %h rdata %h, expected %h", raddr, s_axil_rdata, t_r_exp_data))
                            `CHECK(s_axil_rresp == t_r_exp_resp,
                                   ("R: addr %h rresp %b, expected %b", raddr, s_axil_rresp, t_r_exp_resp))
                            t_r_hold_data = s_axil_rdata;
                            t_r_hold_resp = s_axil_rresp;
                        end else begin
                            `CHECK((s_axil_rdata == t_r_hold_data) && (s_axil_rresp == t_r_hold_resp),
                                   ("R: payload changed while RREADY low (addr %h)", raddr))
                        end
                        `CHECK(!s_axil_arready, ("R: ARREADY high while read data is pending"))
                        if (s_axil_rready) begin
                            t_rd_fin     = 1'b1;
                            t_rd_fin_cyc = t_cyc;
                        end
                    end else if (t_r_seen) begin
                        `FAIL(("R: RVALID dropped before the handshake (addr %h)", raddr))
                    end
                    if (s_axil_arvalid && s_axil_arready) begin
                        t_ar_done    = 1'b1;
                        t_ar_cyc     = t_cyc;
                        t_r_exp_data = tb_mapped(raddr) ? model[raddr[3:2]] : 32'h0000_0000;
                        t_r_exp_resp = tb_mapped(raddr) ? 2'b00 : 2'b10;
                    end
                end else if (!do_rd) begin
                    if (s_axil_rvalid) begin
                        `FAIL(("R: RVALID high with no read in flight"))
                    end
                end else if (t_cyc == t_rd_fin_cyc + 1) begin
                    `CHECK(s_axil_arready && !s_axil_rvalid,
                           ("R: channel not ready the cycle after the response was taken"))
                end

                // ---------------- write channel ----------------
                if (do_wr && !t_wr_fin) begin
                    if (s_axil_bvalid) begin
                        `CHECK(t_wr_cmp >= 0, ("B: BVALID high before both AW and W were accepted"))
                        if (!t_b_seen) begin
                            t_b_seen = 1'b1;
                            t_b_cyc  = t_cyc;
                            `CHECK(((t_cyc - t_wr_cmp) >= 1) && ((t_cyc - t_wr_cmp) <= 2),
                                   ("B: latency %0d cycles, bound is 1 to 2", t_cyc - t_wr_cmp))
                            `CHECK(s_axil_bresp == t_b_exp,
                                   ("B: addr %h bresp %b, expected %b", waddr, s_axil_bresp, t_b_exp))
                            t_b_hold = s_axil_bresp;
                        end else begin
                            `CHECK(s_axil_bresp == t_b_hold, ("B: BRESP changed while BREADY low"))
                        end
                        `CHECK(!s_axil_awready && !s_axil_wready,
                               ("B: AWREADY or WREADY high while a write response is pending"))
                        if (s_axil_bready) begin
                            t_wr_fin     = 1'b1;
                            t_wr_fin_cyc = t_cyc;
                        end
                    end else if (t_b_seen) begin
                        `FAIL(("B: BVALID dropped before the handshake"))
                    end
                    t_aw_hs = s_axil_awvalid && s_axil_awready;
                    t_w_hs  = s_axil_wvalid && s_axil_wready;
                    if (t_aw_hs) t_aw_done = 1'b1;
                    if (t_w_hs)  t_w_done  = 1'b1;
                    if ((t_aw_hs || t_w_hs) && t_aw_done && t_w_done) begin
                        t_wr_cmp = t_cyc;
                        if (tb_mapped(waddr)) begin
                            model[waddr[3:2]] = tb_merge(model[waddr[3:2]], wdat, wstr);
                        end
                    end
                end else if (!do_wr) begin
                    if (s_axil_bvalid) begin
                        `FAIL(("B: BVALID high with no write in flight"))
                    end
                end else if (t_cyc == t_wr_fin_cyc + 1) begin
                    `CHECK(s_axil_awready && s_axil_wready && !s_axil_bvalid,
                           ("B: channel not ready the cycle after the response was taken"))
                end

                t_cyc = t_cyc + 1;
            end
            if (!t_wr_fin || !t_rd_fin) begin
                `FAIL(("timeout: write done %b, read done %b", t_wr_fin, t_rd_fin))
            end
            @(negedge aclk);
            idle_inputs;
            #4;
            `CHECK(!s_axil_bvalid && !s_axil_rvalid, ("idle: a response is still valid"))
            `CHECK(s_axil_awready && s_axil_wready && s_axil_arready,
                   ("idle: READY low the cycle after the response was taken"))
        end
    endtask

    task wr;
        input [3:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        begin
            run_txn(1'b1, addr, data, strb, 0, 0, 0, 1'b0, 4'h0, 0, 0);
        end
    endtask

    task rd;
        input [3:0] addr;
        begin
            run_txn(1'b0, 4'h0, 32'h0000_0000, 4'h0, 0, 0, 0, 1'b1, addr, 0, 0);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {(8*64){1'b0}};
        plus_ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        lfsr    = 32'h1234_5678;

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0000_0000;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        model_clear;

        do_reset;

        // 1. Reset values of every register.
        for (k = 0; k < 4; k = k + 1) begin
            a = {k[1:0], 2'b00};
            rd(a);
        end

        // 2. Write then read every register, full strobes.
        for (k = 0; k < 4; k = k + 1) begin
            a = {k[1:0], 2'b00};
            rnd_step;
            wr(a, lfsr, 4'hF);
            rd(a);
        end

        // 3. Byte enables: partial and empty strobes.
        wr(4'h4, 32'hFFFF_FFFF, 4'hF);
        wr(4'h4, 32'h0000_0000, 4'b0101);
        rd(4'h4);
        wr(4'h4, 32'h1234_5678, 4'b1000);
        rd(4'h4);
        wr(4'h4, 32'hDEAD_BEEF, 4'b0000);
        rd(4'h4);
        wr(4'h8, 32'h1122_3344, 4'b0001);
        rd(4'h8);
        wr(4'h8, 32'h5566_7788, 4'b0010);
        rd(4'h8);
        wr(4'h8, 32'h99AA_BBCC, 4'b0100);
        rd(4'h8);
        wr(4'h8, 32'hDDEE_FF00, 4'b1000);
        rd(4'h8);

        // 4. AW before W, W before AW, both together.
        run_txn(1'b1, 4'hC, 32'hA0A0_0001, 4'hF, 0, 3, 0, 1'b0, 4'h0, 0, 0);
        rd(4'hC);
        run_txn(1'b1, 4'hC, 32'hA0A0_0002, 4'hF, 3, 0, 0, 1'b0, 4'h0, 0, 0);
        rd(4'hC);
        run_txn(1'b1, 4'hC, 32'hA0A0_0003, 4'hF, 0, 0, 0, 1'b0, 4'h0, 0, 0);
        rd(4'hC);
        run_txn(1'b1, 4'h0, 32'hA0A0_0004, 4'hF, 0, 1, 0, 1'b0, 4'h0, 0, 0);
        run_txn(1'b1, 4'h4, 32'hA0A0_0005, 4'h3, 1, 0, 0, 1'b0, 4'h0, 0, 0);
        rd(4'h0);
        rd(4'h4);

        // 5. B and R back-pressure.
        run_txn(1'b1, 4'h8, 32'hBEEF_0001, 4'hF, 0, 0, 4, 1'b0, 4'h0, 0, 0);
        run_txn(1'b1, 4'h8, 32'hBEEF_0002, 4'hF, 2, 0, 3, 1'b0, 4'h0, 0, 0);
        run_txn(1'b0, 4'h0, 32'h0000_0000, 4'h0, 0, 0, 0, 1'b1, 4'h8, 0, 5);
        run_txn(1'b0, 4'h0, 32'h0000_0000, 4'h0, 0, 0, 0, 1'b1, 4'h8, 2, 3);

        // 6. SLVERR policy for unmapped (misaligned) addresses.
        run_txn(1'b1, 4'h5, 32'h0BAD_0BAD, 4'hF, 0, 0, 0, 1'b0, 4'h0, 0, 0);
        rd(4'h4);
        run_txn(1'b1, 4'hE, 32'h0BAD_0BAD, 4'hF, 0, 0, 2, 1'b0, 4'h0, 0, 0);
        rd(4'hC);
        run_txn(1'b1, 4'h1, 32'h0BAD_0BAD, 4'hF, 3, 0, 3, 1'b0, 4'h0, 0, 0);
        rd(4'h0);
        rd(4'h5);
        run_txn(1'b0, 4'h0, 32'h0000_0000, 4'h0, 0, 0, 0, 1'b1, 4'h3, 0, 3);
        rd(4'hE);

        // 7. Reads and writes at the same time.
        run_txn(1'b1, 4'h8, 32'hC0DE_0001, 4'hF, 0, 0, 0, 1'b1, 4'hC, 0, 0);
        run_txn(1'b1, 4'h0, 32'hC0DE_0002, 4'hF, 0, 0, 0, 1'b1, 4'h0, 0, 0);
        run_txn(1'b1, 4'h0, 32'hC0DE_0003, 4'hF, 2, 2, 0, 1'b1, 4'h0, 0, 0);
        run_txn(1'b1, 4'h0, 32'hC0DE_0004, 4'hF, 0, 0, 0, 1'b1, 4'h0, 3, 0);
        run_txn(1'b1, 4'h4, 32'hC0DE_0005, 4'hF, 1, 0, 3, 1'b1, 4'h4, 0, 4);
        rd(4'h0);
        rd(4'h4);
        rd(4'h8);

        // 8. Pseudo-random traffic.
        for (k = 0; k < 80; k = k + 1) begin
            rnd_step;
            v = lfsr;
            rnd_step;
            d = lfsr;
            r_rd    = v[26];
            r_wr    = v[27] | ~v[26];
            r_waddr = (v[4] | v[5]) ? {v[3:2], 2'b00} : v[3:0];
            r_strb  = v[28] ? 4'hF : v[9:6];
            r_raddr = (v[20] | v[21]) ? {v[19:18], 2'b00} : v[19:16];
            dly_aw  = {30'b0, v[11:10]};
            dly_w   = {30'b0, v[13:12]};
            dly_b   = {30'b0, v[15:14]};
            dly_ar  = {30'b0, v[23:22]};
            dly_r   = {30'b0, v[25:24]};
            run_txn(r_wr, r_waddr, d, r_strb, dly_aw, dly_w, dly_b,
                    r_rd, r_raddr, dly_ar, dly_r);
        end
        rd(4'h0);
        rd(4'h4);
        rd(4'h8);
        rd(4'hC);

        // 9. Reset discards a half-accepted write (AW without W).
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h8;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b1;
        #4;
        `CHECK(s_axil_awready, ("reset test: AWREADY low before the half write"))
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        aresetn        = 1'b0;
        @(negedge aclk);
        aresetn = 1'b1;
        model_clear;
        s_axil_wvalid = 1'b1;
        s_axil_wdata  = 32'hFEED_FACE;
        s_axil_wstrb  = 4'hF;
        #4;
        `CHECK(s_axil_wready && !s_axil_bvalid, ("reset test: W not accepted after reset"))
        for (k = 0; k < 3; k = k + 1) begin
            @(negedge aclk);
            s_axil_wvalid = 1'b0;
            s_axil_wdata  = 32'h0000_0000;
            #4;
            `CHECK(!s_axil_bvalid, ("reset test: a write completed with an AW accepted before reset"))
            `CHECK(!s_axil_wready && s_axil_awready, ("reset test: W not held while waiting for its AW"))
        end
        // The held W completes with a fresh AW to REG1.
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h4;
        s_axil_bready  = 1'b1;
        #4;
        `CHECK(s_axil_awready && !s_axil_bvalid, ("reset test: AWREADY low for the second half"))
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        #4;
        `CHECK(s_axil_bvalid && (s_axil_bresp == 2'b00), ("reset test: held W did not complete with its AW"))
        model[1] = 32'hFEED_FACE;
        @(negedge aclk);
        idle_inputs;
        rd(4'h4);
        rd(4'h8);

        // 10. Reset while a write and a read response wait under back-pressure.
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h0;
        s_axil_wvalid  = 1'b1;
        s_axil_wdata   = 32'h1111_2222;
        s_axil_wstrb   = 4'hF;
        s_axil_bready  = 1'b0;
        s_axil_arvalid = 1'b1;
        s_axil_araddr  = 4'h4;
        s_axil_rready  = 1'b0;
        #4;
        `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("reset test: READY low before traffic"))
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        #4;
        `CHECK(s_axil_bvalid && s_axil_rvalid, ("reset test: responses not pending before reset"))
        @(negedge aclk);
        aresetn = 1'b0;
        @(negedge aclk);
        aresetn = 1'b1;
        #4;
        `CHECK(!s_axil_bvalid && !s_axil_rvalid, ("reset test: response survived reset"))
        `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("reset test: READY low after reset"))
        model_clear;
        rd(4'h0);
        rd(4'h4);
        rd(4'h8);
        rd(4'hC);
        wr(4'hC, 32'h600D_CAFE, 4'hF);
        rd(4'hC);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
